require_once __DIR__.'/../includes/authorization.php';require_role('admin');require_once __DIR__.'/../includes/Repositories/OrderRepository.php';$repo=new OrderRepository();$transitions=['requested'=>['accepted','cancelled'],'accepted'=>['completed','cancelled'],'completed'=>[],'cancelled'=>[]];$errors=[];
if(is_post()){if(!verify_csrf()){flash('error','Sesi formulir tidak valid.');redirect(page_url('admin-orders'));}$id=filter_input(INPUT_POST,'order_id',FILTER_VALIDATE_INT);$new=$_POST['status']??'';$st=$id?db()->prepare('SELECT status FROM orders WHERE id=?'):null;if($st)$st->execute([$id]);$cur=$st?$st->fetchColumn():false;if(!$id||!$cur||!isset($transitions[$cur])||!in_array($new,$transitions[$cur],true))$errors[]='Transisi status tidak valid.';else{$repo->setStatus((int)$id,$new);flash('success','Status transaksi diperbarui.');redirect(page_url('admin-orders'));}}
