?><section class="section-padding page-section"><div class="container"><div class="page-toolbar"><?=back_link('admin-dashboard','Kembali ke dashboard admin')?></div><div class="section-heading mb-4"><span class="eyebrow">Admin</span><h2>Kelola <em>transaksi.</em></h2><p class="text-muted">Pantau order dan transisi status. Histori tidak dihapus.</p></div><?php if($errors):?><div class="alert alert-danger"><?=implode('<br>',array_map('e',$errors))?></div><?php endif;?><?php foreach($orders as $o):?><div class="glass-card p-4 mb-3"><div class="d-flex justify-content-between"><div><strong>#<?=intval($o['id'])?></strong><div class="text-muted">Customer: <?=e($o['buyer_name'])?></div><small><?=e($o['created_at'])?></small></div><span class="badge text-bg-light"><?=e($o['status'])?></span></div><div class="mt-2"><strong><?=format_price((int)$o['total'])?></strong> · <?=intval($o['item_count'])?> item</div><?php if($transitions[$o['status']]??[]):?><form class="d-flex gap-2 mt-3" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="order_id" value="<?=intval($o['id'])?>"><select class="form-select" name="status"><?php foreach($transitions[$o['status']] as $s):?><option value="<?=$s?>"><?=$s?></option><?php endforeach;?></select><button class="btn btn-primary">Simpan status</button></form><?php endif;?></div><?php endforeach;?></div></section><?php require __DIR__.'/../includes/footer.php'; ?>